 [W("station", "/ˈsteɪʃn/", "noun", "вокзал, станція", "Where is the station?", "Де вокзал?"),
  W("supermarket", "/ˈsuːpəmɑːkɪt/", "noun", "супермаркет", "The supermarket is open.", "Супермаркет відчинений."),
  W("pharmacy", "/ˈfɑːməsi/", "noun", "аптека", "Is there a pharmacy near here?", "Тут поблизу є аптека?"),
  W("post office", "/ˈpəʊst ˌɒfɪs/", "noun", "пошта", "The post office is closed.", "Пошта зачинена."),
  W("park", "/pɑːk/", "noun", "парк", "Let's go to the park.", "Ходімо в парк."),
  W("museum", "/mjuˈziːəm/", "noun", "музей", "The museum is free.", "Музей безкоштовний."),
  W("square", "/skweə/", "noun", "площа", "The main square.", "Головна площа.")],
