  W("crowded", "/ˈkraʊdɪd/", A, "переповнений людьми", "The centre is crowded.", "У центрі повно людей."),
  W("safe", "/seɪf/", A, "безпечний", "It's a safe place.", "Це безпечне місце."),
  W("dangerous", "/ˈdeɪndʒərəs/", A, "небезпечний", "A dangerous road.", "Небезпечна дорога."),
